{"file_path":"src/simulate.js","content":"// Policy state machines. Each policy instance keeps one state per key.

class TokenBucketPolicy {
  constructor(def) {
    this.name = def.name
    this.capacity = def.capacity
    this.refill = def.refill
    this.per = def.per
    this.states = new Map() // key -> { tokensNum: BigInt (units of 1/per), lastTick: BigInt }
  }

  advance(key, tick) {
    let state = this.states.get(key)
    if (!state) {
      state = { tokensNum: this.capacity * this.per, lastTick: tick }
      this.states.set(key, state)
      return
    }
    const delta = tick - state.lastTick
    if (delta > 0n) {
      const capNum = this.capacity * this.per
      let next = state.tokensNum + this.refill * delta
      if (next > capNum) next = capNum
      state.tokensNum = next
      state.lastTick = tick
    }
  }

  allows(key) {
    const state = this.states.get(key)
    return state.tokensNum >= this.per
  }

  record(key) {
    const state = this.states.get(key)
    state.tokensNum -= this.per
  }
}

class SlidingWindowPolicy {
  constructor(def) {
    this.name = def.name
    this.limit = def.limit
    this.span = def.span
    this.states = new Map() // key -> array of recorded ticks (BigInt), ascending
  }

  advance(key, tick) {
    let state = this.states.get(key)
    if (!state) {
      state = []
      this.states.set(key, state)
    }
    const threshold = tick - this.span
    let idx = 0
    while (idx < state.length && state[idx] <= threshold) idx++
    if (idx > 0) state.splice(0, idx)
  }

  allows(key) {
    const state = this.states.get(key)
    return BigInt(state.length) < this.limit
  }

  record(key, tick) {
    const state = this.states.get(key)
    state.push(tick)
  }
}

function buildPolicyInstances(policyDefs) {
  const instances = new Map()
  for (const [name, def] of policyDefs) {
    if (def.kind === 'bucket') {
      instances.set(name, new TokenBucketPolicy(def))
    } else {
      instances.set(name, new SlidingWindowPolicy(def))
    }
  }
  return instances
}

function findRoute(routes, key) {
  let best = null
  for (const route of routes) {
    if (key.startsWith(route.prefix)) {
      if (best === null || route.prefix.length > best.prefix.length) {
        best = route
      }
    }
  }
  return best
}

/**
 * Runs the whole event log against the declared policies and routes.
 * Returns an array of verdicts: { tick, key, allow: boolean, deniedBy: name|null }
 */
export function simulate(program) {
  const { policies, routes, events } = program
  const instances = buildPolicyInstances(policies)
  const verdicts = []

  for (const event of events) {
    const { tick, key } = event
    const route = findRoute(routes, key)
    if (!route) {
      verdicts.push({ tick, key, allow: true, deniedBy: null })
      continue
    }
    const routePolicies = route.policyNames.map((name) => instances.get(name))
    for (const policy of routePolicies) {
      policy.advance(key, tick)
    }
    let deniedBy = null
    for (let i = 0; i < routePolicies.length; i++) {
      if (!routePolicies[i].allows(key)) {
        deniedBy = route.policyNames[i]
        break
      }
    }
    if (deniedBy === null) {
      for (const policy of routePolicies) {
        policy.record(key, tick)
      }
      verdicts.push({ tick, key, allow: true, deniedBy: null })
    } else {
      verdicts.push({ tick, key, allow: false, deniedBy })
    }
  }

  return verdicts
}
"}

