{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { parseProgram } from './parse.js'
import { simulate } from './simulate.js'
import { CliError } from './errors.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  while (true) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.slice(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }
  const mode = args[0]

  const input = readStdin()

  let program
  try {
    program = parseProgram(input)
  } catch (err) {
    if (err instanceof CliError) {
      process.stderr.write(err.message + '\n')
      process.exit(2)
    }
    throw err
  }

  const verdicts = simulate(program)

  if (mode === 'replay') {
    const lines = verdicts.map((v) => {
      if (v.allow) return `${v.tick} ${v.key} allow`
      return `${v.tick} ${v.key} deny ${v.deniedBy}`
    })
    process.stdout.write(lines.length > 0 ? lines.join('\n') + '\n' : '')
  } else {
    const perKey = new Map()
    let totalAllowed = 0n
    let totalDenied = 0n
    for (const v of verdicts) {
      let entry = perKey.get(v.key)
      if (!entry) {
        entry = { allowed: 0n, denied: 0n }
        perKey.set(v.key, entry)
      }
      if (v.allow) {
        entry.allowed += 1n
        totalAllowed += 1n
      } else {
        entry.denied += 1n
        totalDenied += 1n
      }
    }
    const keys = Array.from(perKey.keys()).sort()
    const lines = keys.map((key) => {
      const entry = perKey.get(key)
      return `${key} allowed=${entry.allowed} denied=${entry.denied}`
    })
    lines.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
    process.stdout.write(lines.join('\n') + '\n')
  }
}

main()
"}

